class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_up_to(n: int) -> int:
            s = str(n)
            digits = list(map(int, s))
            length = len(digits)

            @lru_cache(None)
            def dp(pos: int, sum_: int, prod_mod: int, tight: int, started: int, target_sum: int) -> int:
                if pos == length:
                    return 1 if started and sum_ == target_sum and prod_mod == 0 else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    ntight = tight and d == limit
                    nstarted = started or d != 0
                    nsum = sum_ if not nstarted else sum_ + d
                    nprod_mod = prod_mod
                    if nstarted:
                        nprod_mod = (prod_mod * d) % target_sum if target_sum != 0 else 0
                    # If target_sum==0, we skip because sum cannot be zero (positive integer)
                    if target_sum == 0:
                        continue
                    if nsum > target_sum:
                        continue
                    res += dp(pos + 1, nsum, nprod_mod, ntight, nstarted, target_sum)
                return res

            total = 0
            for target_sum in range(1, 82):
                dp.cache_clear()
                total += dp(0, 0, 0, 1, 0, target_sum)
            return total

        return count_up_to(r) - count_up_to(l - 1)
